<template>
  <q-card class="severity-panel">
    <q-card-section>
      <div class="text-h6">{{ title }}</div>
    </q-card-section>

    <q-card-section v-if="isEmpty">
      <div class="text-grey-6 text-center q-pa-md">No data available</div>
    </q-card-section>

    <q-card-section v-else>
      <div ref="chartWrapper" class="chart-wrapper">
        <VueApexCharts
          type="line"
          height="220"
          :options="chartOptions"
          :series="chartSeries"
        />
        <template v-if="!logData">
          <div
            v-for="(pos, i) in labelPositions"
            :key="i"
            class="point-label"
            :style="{ left: pos.x + 'px', top: pos.y + 'px' }"
          >
            <span class="pl-total">T: {{ pos.total }}</span>
            <span class="pl-passed">P: {{ pos.passed }}</span>
            <span class="pl-failed">F: {{ pos.failed }}</span>
            <span class="pl-skipped">S: {{ pos.skipped }}</span>
          </div>
        </template>
      </div>
    </q-card-section>
  </q-card>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import VueApexCharts from 'vue3-apexcharts';
import type { ChartDataPoint } from 'src/services/tests/testStatisticsApi.service';
import type { LogCountPoint } from 'src/services/tests/sentinelLogApi.service';

export interface LabelPos {
  x: number;
  y: number;
  total: number;
  passed: number;
  failed: number;
  skipped: number;
}

export interface ChartOpts {
  categories: string[];
  yAxisTitle: string;
  yAxisMax: number;
}

export default defineComponent({
  name: 'SeverityPanel',

  components: { VueApexCharts },

  props: {
    title: {
      type: String,
      required: true,
    },
    chartData: {
      type: Array as PropType<ChartDataPoint[]>,
      required: true,
    },
    serviceName: {
      type: String,
      required: true,
    },
    logData: {
      type: Array as PropType<LogCountPoint[]>,
      default: undefined,
    },
  },

  data() {
    return {
      primaryColor: '#1976D2' as string,
      labelPositions: [] as LabelPos[],
    };
  },

  computed: {
    isEmpty(): boolean {
      return (this.logData ? this.logData.length : this.chartData.length) === 0;
    },

    chartSeries(): { name: string; data: number[] }[] {
      if (this.logData && this.logData.length > 0) {
        return [{ name: 'Count', data: this.logData.map((p) => p.count) }];
      }
      return [{ name: 'Failed', data: this.chartData.map((p) => p.failed) }];
    },

    chartOptions(): object {
      if (this.logData && this.logData.length > 0) {
        const maxCount = Math.max(...this.logData.map((p) => p.count), 1);
        return this.buildChartOptions({
          categories: this.logData.map((p) => this.formatTimestamp(p.timestamp)),
          yAxisTitle: 'Count',
          yAxisMax: maxCount * 2.5,
        });
      }
      const maxFailed = Math.max(...this.chartData.map((p) => p.failed), 1);
      return this.buildChartOptions({
        categories: this.chartData.map((p) => this.formatTimestamp(p.timestamp)),
        yAxisTitle: 'Failed',
        yAxisMax: maxFailed * 2.5,
      });
    },
  },

  mounted() {
    const cssColor = getComputedStyle(document.documentElement)
      .getPropertyValue('--primary-color')
      .trim();
    if (/^#[0-9a-fA-F]{6}$/.test(cssColor)) {
      this.primaryColor = cssColor;
    }
  },

  methods: {
    formatTimestamp(timestamp: string): string {
      const date = new Date(timestamp);
      const now = new Date();
      const nowDay = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
      const pointDay = new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();
      const daysDiff = Math.round((nowDay - pointDay) / 86400000);
      if (daysDiff === 0) {
        return `${date.getHours().toString().padStart(2, '0')}:${date.getMinutes().toString().padStart(2, '0')}`;
      }
      return `${daysDiff}d`;
    },

    buildChartOptions(opts: ChartOpts): object {
      return {
        chart: {
          type: 'line',
          toolbar: { show: false },
          zoom: { enabled: false },
          animations: { enabled: false },
          events: {
            mounted: (ctx: any) => this.computeLabels(ctx),
            updated: (ctx: any) => this.computeLabels(ctx),
          },
        },
        colors: [this.primaryColor],
        stroke: { curve: 'smooth', width: 2 },
        markers: { size: 5, strokeWidth: 0, hover: { size: 7 } },
        legend: { show: false },
        dataLabels: { enabled: false },
        grid: { borderColor: '#e0e0e0', strokeDashArray: 3 },
        xaxis: {
          categories: opts.categories,
          labels: { style: { fontSize: '10px' } },
        },
        yaxis: {
          min: 0,
          max: opts.yAxisMax,
          title: { text: opts.yAxisTitle, style: { fontSize: '11px' } },
          labels: {
            formatter: (val: number) => Math.round(val).toString(),
            style: { fontSize: '10px' },
          },
        },
        tooltip: { enabled: false },
      };
    },

    computeLabels(chartCtx: any): void {
      const g = chartCtx?.w?.globals;
      if (!g || !g.gridWidth || !g.gridHeight) return;

      const wrapper = this.$refs.chartWrapper as HTMLElement | null;
      if (!wrapper) return;

      const svgEl = wrapper.querySelector('svg');
      if (!svgEl) return;

      const svgRect = svgEl.getBoundingClientRect();
      const wrapperRect = wrapper.getBoundingClientRect();
      const svgLeft = svgRect.left - wrapperRect.left;
      const svgTop = svgRect.top - wrapperRect.top;

      const n = this.chartData.length;
      if (n === 0) return;

      const plotLeft = svgLeft + (g.translateX as number);
      const plotTop = svgTop + (g.translateY as number);
      const plotW = g.gridWidth as number;
      const plotH = g.gridHeight as number;
      const step = n > 1 ? plotW / (n - 1) : 0;

      const minY = (g.minY as number) ?? 0;
      const maxY = (g.maxY as number) || 1;
      const range = maxY - minY || 1;
      const labelOffset = 64;

      this.labelPositions = this.chartData.map((p, i) => ({
        x: plotLeft + i * step,
        y: plotTop + (1 - (p.failed - minY) / range) * plotH - labelOffset,
        total: p.total,
        passed: p.passed,
        failed: p.failed,
        skipped: p.skipped,
      }));
    },
  },
});
</script>

<style scoped>
.severity-panel {
  margin-bottom: 24px;
}

.chart-wrapper {
  position: relative;
  overflow: visible;
}

.point-label {
  position: absolute;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  pointer-events: none;
  line-height: 1.35;
  font-size: 10px;
  font-weight: 600;
  white-space: nowrap;
}

.pl-total   { color: #333; }
.pl-passed  { color: #43a047; }
.pl-failed  { color: #e53935; }
.pl-skipped { color: #f57c00; }
</style>
