<template>
  <q-page class="statistics-dashboard-page q-pa-md">
    <!-- Page Header -->
    <div class="page-header q-mb-lg">
      <div class="row items-center q-gutter-md">
        <div>
          <h4 class="text-h4 q-my-none">Infrastructure Dashboard</h4>
        </div>
        <q-chip color="blue-6" text-color="white" size="lg" class="text-bold">
          {{ currentEnvironment.toUpperCase() }}
        </q-chip>
        <q-space />
        <q-btn-toggle
          v-model="hoursRange"
          toggle-color="primary"
          flat
          :options="[
            { label: '24h', value: 24 },
            { label: '48h', value: 48 },
            { label: '168h', value: 168 },
          ]"
          @update:model-value="onFilterChange"
        />
      </div>
    </div>

    <!-- Loading State -->
    <div v-if="loading" class="loading-state text-center q-pa-xl">
      <q-spinner size="64px" color="primary" />
      <p class="text-grey-7 q-mt-md">Loading test trend data...</p>
    </div>

    <!-- Error State -->
    <q-banner v-if="error" class="bg-negative text-white q-mt-md" rounded>
      <template #avatar>
        <q-icon name="error" />
      </template>
      {{ error }}
      <template #action>
        <q-btn flat label="Retry" @click="fetchData" />
      </template>
    </q-banner>

    <!-- Success State -->
    <div v-if="!loading && !error && data">
      <div class="row q-col-gutter-md">
        <!-- Left column: severity panels stacked -->
        <div class="col-12 col-lg-6">
          <SeverityPanel
            title="Tests Critical Severity"
            :chartData="criticalData"
            serviceName="critical"
          />
          <SeverityPanel
            title="Tests Normal Severity"
            :chartData="normalData"
            serviceName="normal"
          />
        </div>

        <!-- Right column: log panels -->
        <div class="col-12 col-lg-6">
          <!-- Log loading state -->
          <div v-if="logLoading" class="loading-state text-center q-pa-xl">
            <q-spinner size="48px" color="primary" />
            <p class="text-grey-7 q-mt-md">Loading log trend data...</p>
          </div>

          <!-- Log error state -->
          <q-banner v-else-if="logError" class="bg-negative text-white" rounded>
            <template #avatar>
              <q-icon name="error" />
            </template>
            {{ logError }}
            <template #action>
              <q-btn flat label="Retry" @click="fetchLogData" />
            </template>
          </q-banner>

          <!-- Log success state: Critical and Error log panels -->
          <div v-else-if="logData">
            <SeverityPanel
              title="Critical Logs"
              :chartData="[]"
              serviceName="critical-logs"
              :logData="criticalLogCountData"
            />
            <SeverityPanel
              title="Error Logs"
              :chartData="[]"
              serviceName="error-logs"
              :logData="errorLogCountData"
            />
          </div>
        </div>
      </div>
    </div>
  </q-page>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { getCurrentEnvironment } from 'src/pages/APIs';
import {
  testStatisticsApiService,
  sentinelLogApiService,
  transformTrendToChartData,
  transformHourlyToLogChartData,
  transformLogLevelToCountSeries,
} from 'src/services/tests';
import type {
  AllureTestResultsResponse,
  ChartDataPoint,
} from 'src/services/tests/testStatisticsApi.service';
import type {
  SentinelLogTrendsResponse,
  LogCountPoint,
} from 'src/services/tests/sentinelLogApi.service';
import { logger } from 'src/utils/logger';
import SeverityPanel from './SeverityPanel.vue';

const HOURS_TO_DAYS: Record<number, number> = { 24: 1, 48: 2, 168: 7 };

export default defineComponent({
  name: 'StatisticsDashboard',

  components: { SeverityPanel },

  data() {
    return {
      loading: true,
      error: null as string | null,
      data: null as AllureTestResultsResponse | null,
      hoursRange: 168,
      logLoading: false,
      logError: null as string | null,
      logData: null as SentinelLogTrendsResponse | null,
    };
  },

  computed: {
    currentEnvironment(): string {
      const env = getCurrentEnvironment();
      return env === 'local' ? 'dev' : env;
    },

    criticalData(): ChartDataPoint[] {
      if (!this.data?.trend) return [];
      return transformTrendToChartData(this.data.trend, 'critical');
    },

    normalData(): ChartDataPoint[] {
      if (!this.data?.trend) return [];
      return transformTrendToChartData(this.data.trend, 'normal');
    },

    criticalLogCountData(): LogCountPoint[] {
      if (!this.logData?.timeseries) return [];
      const points = transformHourlyToLogChartData(this.logData.timeseries);
      return transformLogLevelToCountSeries(points, 'critical');
    },

    errorLogCountData(): LogCountPoint[] {
      if (!this.logData?.timeseries) return [];
      const points = transformHourlyToLogChartData(this.logData.timeseries);
      return transformLogLevelToCountSeries(points, 'error');
    },
  },

  mounted() {
    this.fetchData();
    this.fetchLogData();
  },

  methods: {
    hoursToDays(hours: number): number {
      return HOURS_TO_DAYS[hours] ?? 7;
    },

    async fetchData(): Promise<void> {
      this.loading = true;
      this.error = null;
      try {
        this.data = await testStatisticsApiService.getAllureTestResults(
          this.hoursToDays(this.hoursRange),
          this.currentEnvironment
        );
      } catch (err: any) {
        logger.error('[StatisticsDashboard] Failed to fetch test trend data:', err);
        this.error = 'Failed to load test trend data. Please try again.';
      } finally {
        this.loading = false;
      }
    },

    async fetchLogData(): Promise<void> {
      this.logLoading = true;
      this.logError = null;
      try {
        this.logData = await sentinelLogApiService.getLogTrends(this.hoursRange);
      } catch (err: any) {
        logger.error('[StatisticsDashboard] Failed to fetch log trend data:', err);
        this.logError = 'Failed to load log trend data. Please try again.';
      } finally {
        this.logLoading = false;
      }
    },

    onFilterChange(): void {
      void this.fetchData();
      void this.fetchLogData();
    },
  },
});
</script>

